// Handle both regular messages and inline keyboard callbacks
const msg      = $json.message;
const callback = $json.callback_query;

let command, args, chatId, msgId, callbackQueryId;

if (callback) {
  // Inline keyboard button pressed
  const data = callback.data || '';
  const colonIdx = data.indexOf(':');
  command         = colonIdx >= 0 ? data.slice(0, colonIdx) : data;
  args            = colonIdx >= 0 ? data.slice(colonIdx + 1) : '';
  chatId          = callback.message?.chat?.id?.toString() || '';
  msgId           = callback.message?.message_id;
  callbackQueryId = callback.id;
} else {
  // Regular text message
  const text = (msg?.text || '').trim();
  chatId = msg?.chat?.id?.toString() || '';
  msgId  = msg?.message_id;
  callbackQueryId = null;

  if (text.startsWith('/search')) {
    command = 'search';
    args    = text.replace(/^\/search\s*/i, '').trim();
  } else if (text.startsWith('/latest')) {
    command = 'latest';
    const match = text.match(/(\d+)/);
    args = match ? match[1] : '5';
  } else if (text.startsWith('/help')) {
    command = 'help';
    args    = '';
  } else {
    command = 'unknown';
    args    = '';
  }
}

return { json: { command, args, chatId, msgId, callbackQueryId } };

const chatId = $('Parse Command').first().json.chatId;
const data   = $json;

const sourcesText = (data.sources || []).slice(0, 5).map((s, i) =>
  `${i + 1}. [${s.title}](${s.url})\n   _${s.relevance_to_query || ''}_`
).join('\n\n');

const confidence = data.confidence ? `\n\n📊 *Confidence:* ${data.confidence}` : '';

const text = [
  `🔍 *Query:* ${data.query}`,
  '',
  data.answer || '_No answer generated._',
  confidence,
  sourcesText ? `\n\n📄 *Sources:*\n${sourcesText}` : '\n\n_No relevant papers found._'
].join('\n');

return { json: { chatId, text } };

const limit = Math.min(parseInt($json.args) || 5, 10);
const chatId = $json.chatId;

// Scroll the arxiv_papers collection ordered by score (proxy for recency)
// Qdrant scroll returns points in insertion order by default
const response = await fetch('http://qdrant:6333/collections/arxiv_papers/points/scroll', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify({
    limit,
    with_payload: true,
    order_by: { key: 'metadata.ingested_at', direction: 'desc' }
  })
});

if (!response.ok) {
  const err = await response.text();
  throw new Error(`Qdrant scroll failed: ${err}`);
}

const data = await response.json();
const points = (data.result?.points || []).map(p => ({
  title:     p.payload?.metadata?.title     || p.payload?.title     || 'Untitled',
  url:       p.payload?.metadata?.url       || p.payload?.url       || '',
  relevance: p.payload?.metadata?.relevance || p.payload?.relevance || '',
  tags:      p.payload?.metadata?.tags      || p.payload?.tags      || []
}));

return { json: { chatId, papers: points } };

const { chatId, papers } = $json;

if (!papers || papers.length === 0) {
  return { json: { chatId, text: '📭 No papers found in the database yet.' } };
}

const lines = papers.map((p, i) => {
  const tags = Array.isArray(p.tags) ? p.tags.join(', ') : p.tags || '';
  const rel  = p.relevance ? ` · ${p.relevance}` : '';
  return `${i + 1}. [${p.title}](${p.url})\n   🏷️ ${tags}${rel}`;
});

const text = `📚 *Latest papers:*\n\n${lines.join('\n\n')}`;
return { json: { chatId, text } };

const chatId = $json.chatId;
const text = [
  '🤖 *ResearchFlow AI — Commands*',
  '',
  '`/search <question>` — Ask a question and get a cited answer from stored papers',
  '_Example: /search How do mixture of experts models scale?_',
  '',
  '`/latest [n]` — Show the n most recently ingested papers (default 5, max 10)',
  '_Example: /latest 3_',
  '',
  '`/help` — Show this message'
].join('\n');
return { json: { chatId, text } };

const chatId = $json.chatId;
const text = '❓ Unknown command. Send /help to see available commands.';
return { json: { chatId, text } };

// Fetch the paper from Qdrant by URL, then call OpenAI
// for a deeper summary including methodology and limitations.
const paperUrl = $json.args;
const chatId   = $json.chatId;

// 1. Search Qdrant for the paper by URL metadata field
const searchResp = await fetch('http://qdrant:6333/collections/arxiv_papers/points/scroll', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify({
    filter: {
      must: [{ key: 'metadata.url', match: { value: paperUrl } }]
    },
    limit: 1,
    with_payload: true
  })
});

const searchData = await searchResp.json();
const point = searchData.result?.points?.[0];

if (!point) {
  return { json: { chatId, text: '❌ Paper not found in the database.' } };
}

const meta   = point.payload?.metadata || point.payload || {};
const title  = meta.title  || 'Unknown title';
const stored = point.payload?.document || meta.abstract || '';

// 2. Call GPT-4o for a deeper analysis
const gptResp = await fetch('https://api.openai.com/v1/chat/completions', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${$vars.OPENAI_API_KEY}`
  },
  body: JSON.stringify({
    model: 'gpt-4o',
    max_tokens: 800,
    messages: [
      {
        role: 'system',
        content: 'You are a research assistant. Given a paper summary, produce a deeper analysis covering: (1) Methodology in detail — architecture, training procedure, key equations if any; (2) Limitations and open questions; (3) Practical applications; (4) Related work it builds on. Be technical but concise. Use plain text, no markdown headers.'
      },
      {
        role: 'user',
        content: `Title: ${title}\n\nSummary:\n${stored}`
      }
    ]
  })
});

const gptData = await gptResp.json();
const analysis = gptData.choices?.[0]?.message?.content || 'Could not generate analysis.';

const text = [
  `🔍 *Deep analysis: ${title}*`,
  '',
  analysis,
  '',
  `🔗 ${paperUrl}`
].join('\n');

return { json: { chatId, text } };

// Find the Qdrant point for this paper and set user_rating: -1
const paperUrl = $json.args;
const chatId   = $json.chatId;

// Scroll to find the point ID
const scrollResp = await fetch('http://qdrant:6333/collections/arxiv_papers/points/scroll', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify({
    filter: { must: [{ key: 'metadata.url', match: { value: paperUrl } }] },
    limit: 1,
    with_payload: false
  })
});

const scrollData = await scrollResp.json();
const pointId = scrollData.result?.points?.[0]?.id;

if (!pointId) {
  return { json: { chatId, text: '❌ Paper not found — cannot update rating.' } };
}

// PATCH the payload
const patchResp = await fetch(`http://qdrant:6333/collections/arxiv_papers/points/payload`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify({
    payload: { 'metadata.user_rating': -1, 'metadata.user_rated_at': new Date().toISOString() },
    points: [pointId]
  })
});

if (!patchResp.ok) {
  const err = await patchResp.text();
  throw new Error(`Qdrant PATCH failed: ${err}`);
}

return { json: { chatId, text: '⏭ Got it — this paper will be deprioritised in future searches.' } };

// Find the Qdrant point for this paper and set user_rating: 1
const paperUrl = $json.args;
const chatId   = $json.chatId;

const scrollResp = await fetch('http://qdrant:6333/collections/arxiv_papers/points/scroll', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify({
    filter: { must: [{ key: 'metadata.url', match: { value: paperUrl } }] },
    limit: 1,
    with_payload: false
  })
});

const scrollData = await scrollResp.json();
const pointId = scrollData.result?.points?.[0]?.id;

if (!pointId) {
  return { json: { chatId, text: '❌ Paper not found — cannot update rating.' } };
}

const patchResp = await fetch(`http://qdrant:6333/collections/arxiv_papers/points/payload`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify({
    payload: { 'metadata.user_rating': 1, 'metadata.user_rated_at': new Date().toISOString() },
    points: [pointId]
  })
});

if (!patchResp.ok) {
  const err = await patchResp.text();
  throw new Error(`Qdrant PATCH failed: ${err}`);
}

return { json: { chatId, text: '🔖 Saved! This paper is now in your library. It will be used as a quality signal for future prompt tuning.' } };
